      "reviewCount": 1288,
      "description": "Modernes holländisches Pfannkuchenrestaurant im Ferienhotel Der Brabander in Winterberg. Bekannt für eine riesige Auswahl an über 70 fantasievollen süßen und pikanten Pfannkuchen, gemütliche Atmosphäre und eine einladende Sonnenterrasse.",
      "description_nl": "Modern Nederlands pannenkoekenhuis bij Vakantiehotel Der Brabander in Winterberg. Beroemd om meer dan 70 fantasierijke zoete en hartige pannenkoeken, een gezellige sfeer en een ruim zonneterras.",
      "extendedDescription": "Das Pannenkoekenhuis Der Brabander am Waltenberg 61 (direkt im Vakantiehotel Der Brabander) ist ein beliebtes Restaurant für Familien, Urlauber und Genießer in Winterberg. Nach traditioneller holländischer Art werden hier über 70 verschiedene Pfannkuchenspezialitäten frisch aufgetischt – von klassischen süßen Varianten mit Äpfeln, Zimt oder warmen Kirschen bis hin zu deftig-pikanten Kreationen mit Speck, Käse und Schinken.\n\nDas moderne Lokal bietet Speisen vor Ort sowie Gerichte zum Mitnehmen, ist rollstuhlgerecht gestaltet und zeichnet sich durch besondere Kinderfreundlichkeit aus: Kinder freuen sich über die Spielecke sowie den beliebten Kuschelpfannkuchen, bei dem sie sich ein Kuscheltier aussuchen dürfen. Bei schönem Wetter lädt die große Sonnenterrasse mit Blick auf das rege Treiben am Waltenberg zum Verweilen ein.",
      "extendedDescription_nl": "Pannenkoekenhuis Der Brabander aan de Am Waltenberg 61 (in Vakantiehotel Der Brabander) is een geliefde culinaire hotspot voor gezinnen en vakantiegangers in Winterberg. Volgens traditioneel Nederlands recept worden hier ruim 70 verschillende pannenkoeken bereid – van zoete klassiekers met appel, kaneel of warme kersen tot hartige varianten met spek, kaas en champignons.\n\nHet moderne restaurant is rolstoeltoegankelijk en bijzonder kindvriendelijk met een eigen speelhoek en de beroemde knuffelpannenkoek. Gasten kunnen zowel ter plaatse dineren als gerechten afhalen. Op zonnige dagen is het heerlijk toeven op het grote terras.",
