    extendedDescription: 'Die VELTINS-EisArena auf der Winterberger Kappe zählt zu den prestigeträchtigsten Wettkampfstätten des internationalen Kufensports. Die rund 1.600 Meter lange Hochgeschwindigkeits-Eisrinne verfügt über 15 anspruchsvolle Kurven und gilt als Bundes- und Landesstützpunkt für den Bob-, Rodel- und Skeletonsport.\n\nNeben packenden Großereignissen wie Weltcup-Rennen und internationalen Meisterschaften bietet die Bahn auch für Urlauber und Sportbegeisterte unvergessliche Erlebnisse: Bei geführten Bobbahn-Besichtigungen erhalten Gäste faszinierende Einblicke hinter die Kulissen der Kurven und Kältetechnik. Im Winter locken rasante Taxibob-Fahrten im Original-Viererbob mit erfahrenem Rennpiloten sowie Gästerodel-Angebote. Betrieben wird die moderne Sportstätte von der [Sportzentrum Winterberg Hochsauerland GmbH](/ski-bike-sport/sport-und-outdoor/sportzentrum-winterberg-hochsauerland).',
    description_nl: 'De VELTINS-EisArena in Winterberg is een van de snelste en modernste kunstijsbanen ter wereld voor bobsleeën, rodelen en skeleton, en het decor van wereldbekers, wereldkampioenschappen en rondleidingen.',
    extendedDescription_nl: 'De VELTINS-EisArena op de Erlebnisberg Kappe in Winterberg behoort tot de absolute wereldtop in de sleesport. De circa 1.600 meter lange hogesnelheidsbaan telt 15 uitdagende bochten en dient als officieel nationaal trainingscentrum voor bobsleeën, rodelen en skeleton.\n\nNaast internationale topsportevenementen kunnen bezoekers de ijsbaan van dichtbij beleven via deskundige rondleidingen achter de schermen, sensationele taxibob-ritten in een echte viermansbob en gastenrodelen in het winterseizoen. De arena wordt geëxploiteerd door [Sportzentrum Winterberg Hochsauerland GmbH](/nl/ski-fiets-sport/sport-en-outdoor/sportzentrum-winterberg-hochsauerland).',
