    extendedDescription: "Das Studio Entspannungselemente von Astrid Schönhense an der Günninghauser Straße 11 in Winterberg ist ein Rückzugsort für Erholung, Körperbewusstsein und innere Balance im Hochsauerland. Mit fundierter Ausbildung und langjähriger Praxis begleitet Astrid Schönhense Teilnehmer aller Erfahrungsstufen – vom Einsteiger bis zum Fortgeschrittenen.\n\nDas Kursprogramm umfasst facettenreiche Hatha- und Vinyasa-Yogastunden, regenerative Yin-Yoga-Sessions, Klangmassagen mit tibetischen Klangschalen sowie thematische Yoga-Retreats mitten in der sauerländischen Natur. Neben den Kursen vor Ort im Studio werden regelmäßige Online-Klassen angeboten, sodass Flexibilität und Kontinuität stets gewährleistet sind.",
    extendedDescription_nl: "Studio Entspannungselemente van Astrid Schönhense aan de Günninghauser Straße 11 in Winterberg biedt een oase van rust, vitaliteit en innerlijke harmonie in het Sauerland. Astrid Schönhense begeleidt zowel beginners als gevorderden met persoonlijke aandacht en diepgaande vakkennis.\n\nHet aanbod omvat dynamische Hatha- en Vinyasa-yoga, ontspannende Yin Yoga, klankschaaltherapie en meerdaagse yogaretreats in de prachtige natuur rondom Winterberg. Dankzij het aanbod van zowel fysieke lessen in de sfeervolle studio als interactieve online sessies kunnen deelnemers flexibel werken aan lichaam en geest.",
