    description_nl: "Modern en hoogwaardig ingericht vakantieappartement aan de Am Waltenberg, vlak bij de skiliften en wandelroutes van Winterberg. Ideaal voor koppels, gezinnen en actieve vakantiegangers.",
    extendedDescription: "Das Apartment Winterberg Magic Mountain (Wohnung 5) am Waltenberg 70 befindet sich in bester Ausgangslage für einen abwechslungsreichen Sommer- und Winterurlaub in Winterberg. Das helle, liebevoll im modernen Alpin-Stil eingerichtete Apartment bietet Platz für komfortables Wohnen mit voll ausgestatteter Küche, modernem Badezimmer, gemütlichem Wohn- und Essbereich sowie schnellem WLAN.\n\nDie Talstationen des Skiliftkarussells Winterberg, der Bikepark sowie der Erlebnisberg Kappe sind schnell erreichbar. Gleichzeitig lässt sich das lebendige Stadtzentrum mit seinen Restaurants, Cafés und Einkaufsmöglichkeiten bequem zu Fuß erkunden. Ein eigener Parkplatz sowie ein sicherer Abstellplatz für Ski- und Fahrradausrüstung runden den Aufenthalt ab.",
