    description: "Zertifizierte Fach- und Vorsorgeklinik für Mutter-Kind-Kuren und Vater-Kind-Kuren im heilklimatischen Kurort Winterberg. Ganzheitliche medizinische, psychologische und physiotherapeutische Betreuung.",
    description_nl: "Gecertificeerde gespecialiseerde revalidatie- en kuurkliniek voor moeder-en-kind- en vader-en-kind-kuren in het geneeskrachtige kuuroord Winterberg. Holistische medische, psychologische en fysiotherapeutische zorg.",
    extendedDescription: "Die Mutter-Kind-Klinik St. Ursula an der Ursulinenstraße 26 in Winterberg ist eine anerkannte Vorsorge- und Rehabilitationseinrichtung der katholischen Trägerschaft für Mütter, Väter und deren Kinder. Umgeben von der wohltuenden Mittelgebirgslandschaft des heilklimatischen Höhenkurorts bietet die Klinik optimale Bedingungen zur physischen und psychischen Regeneration.\n\nDas multidisziplinäre Team aus Fachärzten, Psychologen, Physiotherapeuten, Pädagogen und Ernährungsberatern erarbeitet individuelle Behandlungspläne. Schwerpunkte bilden unter anderem Erschöpfungszustände, Atemwegserkrankungen, Stoffwechselstörungen, psychosomatische Beschwerden sowie Erkrankungen des Bewegungsapparates. Während der Therapiezeiten werden Kinder in altersgerechten Gruppen von erfahrenem Fachpersonal liebevoll gefördert.",
    extendedDescription_nl: "Mutter-Kind-Klinik St. Ursula aan de Ursulinenstraße 26 in Winterberg is een gerenommeerde instelling voor preventieve en revalidatiekuren voor ouders en hun kinderen. De gezonde berglucht van het kuuroord Winterberg draagt wezenlijk bij aan herstel en nieuwe energie.\n\nEen multidisciplinair team van artsen, psychologen, fysiotherapeuten en pedagogen biedt persoonlijke zorg op maat. Behandelgebieden omvatten overbelasting, stress, aandoeningen aan de luchtwegen en het bewegingsapparaat. Kinderen worden tijdens de behandelingen opgevangen in leeftijdsgerichte groepen met educatieve en recreatieve activiteiten.",
