    description_nl: "Ervaren grondverzet- en grondwerkbedrijf aan de Lamfert in Winterberg. Gespecialiseerd in graafwerkzaamheden, piste- en padenbouw, sloopwerken en winterdienst.",
    extendedDescription: "Snow-Tec an der Straße Lamfert 7 in Winterberg ist ein erfahrener Fachbetrieb für Erdarbeiten, Tiefbauprojekte und winterliche Dienstleistungen im Sauerland. Ausgerüstet mit einem modernen Fuhrpark – bestehend aus Ketten- und Mobilbaggern, Schleppern, Dumpern und Muldenkippern – realisiert das Unternehmen Erdbaumaßnahmen jeder Größenordnung.\n\nZu den Kernkompetenzen zählen Baugrubenaushub, Hangbefestigungen, Geländemodellierungen, Rodungsarbeiten sowie der Pisten- und Wegebau für Liftbetreiber und Forstbetriebe. In der kalten Jahreszeit sorgt Snow-Tec mit leistungsfähiger Räum- und Streutechnik für freie Straßen und Parkflächen.",
    extendedDescription_nl: "Snow-Tec aan de straat Lamfert 7 in Winterberg is gespecialiseerd in grondverzet, grond- en sloopwerken en terreininrichting in het hooggelegen Sauerland. Met een modern machinepark van rupsgraafmachines, trekkers en dumpers worden projecten efficiënt uitgevoerd.\n\nHet bedrijf verzorgt ontgravingen voor nieuwbouw, taludversterkingen, egalisatiewerkzaamheden en aanleg van bos- en skiroutes. Tijdens de wintermaanden biedt Snow-Tec betrouwbare sneeuwruim- en strooidiensten voor bedrijven en beheerders.",
